  -- Rank 173; public.ecommerce_growth_runtime_command_receipt; fixed read-only revalidation query.
     WHEN 34 THEN OPEN v_cursor FOR SELECT CASE WHEN t.installation_id = p_installation_id THEN jsonb_build_object('org_id', t.org_id, 'project_id', t.project_id, 'operation_id', t.operation_id, 'idempotency_key', t.idempotency_key, 'request_hash', t.request_hash, 'dispatch_revision', t.dispatch_revision, 'installation_id', t.installation_id, 'generation', t.generation, 'execution_epoch', t.execution_epoch, 'cutover_group_id', t.cutover_group_id, 'cutover_group_revision', t.cutover_group_revision, 'runtime_revision', t.runtime_revision, 'response', t.response, 'target_receipt_ref', t.target_receipt_ref, 'actor', t.actor, 'occurred_at', t.occurred_at) ELSE CAST(NULL AS jsonb) END AS relations_row, CASE WHEN t.installation_id = ANY(v_previous_ids) THEN jsonb_build_object('org_id', t.org_id, 'project_id', t.project_id, 'operation_id', t.operation_id, 'idempotency_key', t.idempotency_key, 'request_hash', t.request_hash, 'dispatch_revision', t.dispatch_revision, 'installation_id', t.installation_id, 'generation', t.generation, 'execution_epoch', t.execution_epoch, 'cutover_group_id', t.cutover_group_id, 'cutover_group_revision', t.cutover_group_revision, 'runtime_revision', t.runtime_revision, 'response', t.response, 'target_receipt_ref', t.target_receipt_ref, 'actor', t.actor, 'occurred_at', t.occurred_at) ELSE CAST(NULL AS jsonb) END AS predecessors_row, CAST(NULL AS jsonb) AS registry_row, CAST(NULL AS jsonb) AS source_head, CAST(ARRAY[t.response, t.target_receipt_ref] AS jsonb[]) AS json_cells, CAST(NULL AS text) AS raw_authority FROM public.ecommerce_growth_runtime_command_receipt AS t WHERE t.org_id = p_org_id AND t.project_id = p_project_id AND (t.installation_id = p_installation_id OR t.installation_id = ANY(v_previous_ids)) ORDER BY t.org_id, t.project_id, t.operation_id, t.idempotency_key LIMIT 8193;
