  -- Rank 182; public.asset_bundle_artifact; fixed read-only revalidation query.
     WHEN 37 THEN OPEN v_cursor FOR SELECT CAST(NULL AS jsonb) AS relations_row, CAST(NULL AS jsonb) AS predecessors_row, CASE WHEN EXISTS (SELECT 1 FROM public.asset_bundle_version AS v INNER JOIN public.asset_bundle AS b ON b.bundle_pk = v.bundle_pk INNER JOIN pg_catalog.jsonb_to_recordset(v_coordinates) AS k(publisher text, bundle_id text, version text) ON k.publisher = b.publisher AND k.bundle_id = b.bundle_id AND k.version = v.version WHERE v.version_pk = t.version_pk) THEN jsonb_build_object('version_pk', t.version_pk, 'relative_path', t.relative_path, 'digest', t.digest, 'size', t.size, 'media_type', t.media_type) ELSE CAST(NULL AS jsonb) END AS registry_row, CAST(NULL AS jsonb) AS source_head, CAST(ARRAY[] AS jsonb[]) AS json_cells, CAST(NULL AS text) AS raw_authority FROM public.asset_bundle_artifact AS t WHERE EXISTS (SELECT 1 FROM public.asset_bundle_version AS v INNER JOIN public.asset_bundle AS b ON b.bundle_pk = v.bundle_pk INNER JOIN pg_catalog.jsonb_to_recordset(v_coordinates) AS k(publisher text, bundle_id text, version text) ON k.publisher = b.publisher AND k.bundle_id = b.bundle_id AND k.version = v.version WHERE v.version_pk = t.version_pk) ORDER BY t.version_pk, t.relative_path LIMIT 8193;
