      RAISE EXCEPTION 'source head changed' USING ERRCODE='40001'; END IF;
     v_json:=v_row.source_head;
     v_work_rows:=v_work_rows+1;
     v_row_bytes:=octet_length(convert_to(v_json::text,'UTF8'));
     v_work_bytes:=v_work_bytes+v_row_bytes;
