      v_depth:=v_depth_stack[cardinality(v_depth_stack)]; v_depth_stack:=trim_array(v_depth_stack,1);
      v_nodes:=v_nodes+1; v_work_nodes:=v_work_nodes+1;
      IF v_depth>64 OR v_nodes>200000 OR v_work_nodes>800000 THEN RAISE EXCEPTION 'terminal source row JSON budget' USING ERRCODE='54000'; END IF;
