       FOR v_item IN SELECT value FROM pg_catalog.jsonb_each(v_value) UNION ALL SELECT to_jsonb(key) FROM pg_catalog.jsonb_each(v_value) LOOP
        IF v_nodes+cardinality(v_stack)>=200000 THEN RAISE EXCEPTION 'terminal source pending JSON nodes' USING ERRCODE='54000'; END IF;
