    FOREACH v_family IN ARRAY ARRAY['relations','predecessors','registry'] LOOP
     CASE v_family
      WHEN 'relations' THEN v_json:=v_row.relations_row; v_cap:=v_relations_caps[v_stage+1];
      WHEN 'predecessors' THEN v_json:=v_row.predecessors_row; v_cap:=v_predecessors_caps[v_stage+1];
      WHEN 'registry' THEN v_json:=v_row.registry_row; v_cap:=v_registry_caps[v_stage+1];
     END CASE;
     IF v_json IS NULL THEN CONTINUE; END IF;
     v_relation:=v_relation_names[v_stage+1];
     v_work_rows:=v_work_rows+1;
