       FOR v_item IN SELECT value FROM pg_catalog.jsonb_array_elements(v_value) LOOP
        IF v_nodes+cardinality(v_stack)>=200000 THEN RAISE EXCEPTION 'terminal source pending JSON nodes' USING ERRCODE='54000'; END IF;
        v_stack:=array_append(v_stack,v_item); v_depth_stack:=array_append(v_depth_stack,v_depth+1);
       END LOOP;
      END IF;
     END LOOP;
