   END LOOP;
   CLOSE v_cursor;
  END LOOP;
  IF v_packet_bytes IS DISTINCT FROM octet_length(convert_to(v_packet::text,'UTF8')) OR v_packet_bytes>8388608 THEN
   RAISE EXCEPTION 'terminal source final packet width' USING ERRCODE='54000'; END IF;
