  v_stack:=ARRAY[v_packet]; v_depth_stack:=ARRAY[0]; v_nodes:=0;
  WHILE cardinality(v_stack)>0 LOOP
   v_value:=v_stack[cardinality(v_stack)]; v_stack:=trim_array(v_stack,1);
   v_depth:=v_depth_stack[cardinality(v_depth_stack)]; v_depth_stack:=trim_array(v_depth_stack,1);
   v_nodes:=v_nodes+1; v_work_nodes:=v_work_nodes+1;
   IF v_depth>64 OR v_nodes>200000 OR v_work_nodes>800000 THEN
    RAISE EXCEPTION 'terminal source JSON work limit' USING ERRCODE='54000'; END IF;
   IF jsonb_typeof(v_value)='object' THEN
    FOR v_item IN SELECT value FROM pg_catalog.jsonb_each(v_value) UNION ALL SELECT to_jsonb(key) FROM pg_catalog.jsonb_each(v_value) LOOP
     v_stack:=array_append(v_stack,v_item); v_depth_stack:=array_append(v_depth_stack,v_depth+1);
    END LOOP;
   ELSIF jsonb_typeof(v_value)='array' THEN
    FOR v_item IN SELECT value FROM pg_catalog.jsonb_array_elements(v_value) LOOP
     v_stack:=array_append(v_stack,v_item); v_depth_stack:=array_append(v_depth_stack,v_depth+1);
    END LOOP;
   END IF;
  END LOOP;
  IF v_round=0 THEN v_locked_packet:=v_packet; v_locked_locator:=v_locator;
  ELSIF v_locked_packet IS DISTINCT FROM v_packet THEN
   RAISE EXCEPTION 'terminal source fact set changed' USING ERRCODE='40001';
  END IF;
 END LOOP;
 RETURN v_packet;
END;
